import { useMemo, useRef } from "react";
import { useContainerTypeObserver } from "./useContainerTypeObserver";
import { DeviceType } from "./deviceType";
export const useGridSize = () => {
    const ref = useRef(null);
    const gridType = useContainerTypeObserver(ref);
    const isMobile = useMemo(() => gridType === DeviceType.Mobile, [gridType]);
    return [ref, isMobile, gridType];
};
